import sys

# Đọc số nguyên từ stdin (mỗi dòng một số), in TỔNG ra stdout.
# Dòng không phải số nguyên: báo "skip: <dòng>" ra stderr.
total = 0
for line in sys.stdin:
    text = line.strip()
    if text == "":
        continue
    try:
        total += int(text)
    except ValueError:
        print("skip:", text, file=sys.stderr)
print(total)

